import Foundation

private typealias E = EvidenceSeed

/// General follow-ups for people who keep coming back on ordinary charges: driving on a revoked license, small drug
/// possession, shoplifting, a vehicle break-in, a scene outside a store. Each one stands on its own facts.
extension FollowUpCases {
    static let batchBP: [CaseTemplate] = [revokedTaillightStop, revokedWorkTruck, constructionZoneSpeed, consoleBaggie,
                                          pipeInJacket, motelMeth, formulaBag, toolboxPickup, closingTimeLot]

    static let revokedTaillightStop = SmallCases.make(
