        state: [E(.video, 3, "Dash Camera", "The stop at 9:40 p.m.; {D} hands over an expired ID and says the license is 'at home.'"),
                E(.document, 3, "DMV Record", "The license is revoked; a notice was mailed to the address on file and not returned."),
                E(.document, 2, "Stop Report", "A broken left taillight; the car is registered to {DL}.")],
        defense: [E(.statement, 1, "Old Address", "{DL} says the notice went to a house {D.he} moved out of in the winter."),
                  E(.document, 1, "Lease", "A lease for a new apartment that began in February.")],
        role: "Police officer",
        exam: [.direct("What is your assignment?", "\"I'm a police officer, and I make traffic stops at night.\""), .direct("Why did you stop {DL}?", "\"A taillight was broken on {D.his} car, and it was dark, so I pulled it over at about nine-forty.\""), .direct("What did {DL} give you?", "\"An expired state ID, and {D.he} said the license was at home.\""), .direct("What did the records check show?", "\"That {DL}'s license had been revoked since the spring, with the notice mailed to an address on file.\""), .direct("What does your dash camera show?", "\"The stop at nine-forty, and {DL} handing me the ID and saying it was at home.\""), .direct("What did {DL} say?", "\"{D.He} said the notice went to a house {D.he} moved out of in the winter.\""), .cross("{DL} was polite?", "\"Yes, {D.he} was polite, and calm, from the moment I walked up to the window.\""), .cross("{DL}'s address on file was the old one?", "\"I believe so, since the mail wasn't forwarded, and the notice went to the old house.\""), .cross("{DL} wasn't impaired?", "\"No, {D.he} wasn't impaired, and {D.he} didn't smell of alcohol or drugs.\""), .cross("{DL} didn't flee?", "\"No, {D.he} didn't flee, and {D.he} stayed in the car until I asked {D.him} to step out.\""), .cross("{DL} has not updated the address?", "\"Not at the DMV, though {D.he} says {D.he} updated it with the post office.\"")],
        theory: ("{D} drove knowing the license was gone.", "{D} never got the notice."),
        allocution: "\"The notice about my revocation went to my old address, and I never saw it. I had no idea my license was revoked when the officer stopped me for a taillight. I'm sorry for driving without a valid license. I'll fix my address with the DMV and get everything sorted before I get behind the wheel again.\"",
        truths: ("A DMV clerk told {DL} about the revocation at the counter two months earlier.", "{DL}'s mail was going to a P.O. box the DMV never had."),
        defendant: [.direct("Did you drive with a revoked license?", "\"I did, but I didn't know it was revoked. The notice went to my old house.\""), .direct("When did you move?", "\"In the winter. I forgot to update my address with the DMV.\""), .direct("Why did you say the license was at home?", "\"I thought it was. I haven't looked for it in months.\""), .direct("Did you know you should check?", "\"I should have, but I didn't. I thought my license was fine.\""), .direct("What did you do when the officer told you?", "\"I was shocked. I told {OFF.him} I had no idea.\""), .direct("What would you tell the officer?", "\"I'm sorry for the trouble. I'll update my address and get my license back.\""), .cross("You've been cited for driving with a revoked license before, haven't you?", "\"Yes, and I told the court I'd keep my address current. I didn't.\""), .cross("You gave an expired ID?", "\"I did hand over an expired ID, and it was a mistake.\""), .cross("You had been told to update your address?", "\"I had been told to update my address, and I forgot to do it.\""), .cross("You'll pay the fees to reinstate?", "\"Yes, I'll pay the fees to reinstate my license, as soon as I can.\""), .cross("You'll stop driving until then?", "\"Yes, I'll stop driving until I'm licensed, and I'll update my address.\"")],
        openings: ("An officer stopped {D} at 9:40 p.m. for a broken taillight, and a records check showed {D}'s license had been revoked since the spring. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the revocation record is in evidence.", "The defense will say the notice went to an old address and {D} never saw it, and did not know the license was revoked. {D} drove in good faith."),
        closings: ("The revocation has been in effect since the spring, the officer stopped {D} at night, and after {PRIOR} {DL} knew exactly what the revocation required.", "A notice sent to an old address is not notice, and {D} never saw it. The State must prove {D} knew the license was revoked."),
        timeline: [(0, "9:40 p.m.: the stop for a broken taillight."), (0, "9:46 p.m.: the records check comes back revoked."), (1, "The DMV sends its record.")],
        identified: "Stopped at the scene.",
        notDone: ["No one asked the DMV whether the notice was ever returned."],
        mood: .indifferent)

    static let revokedWorkTruck = SmallCases.make(
        key: "story.followup.revokedWorkTruck",
        category: .traffic,
        headlines: ["Driver With Revoked License Stopped at Checkpoint in Work Truck", "Driver Says Boss Ordered the Drive Despite Revoked License"],
        law: "dwlr",
        spec: "Operated a motor vehicle on a highway while {D.his} license was revoked, on {DATE}.",
        ages: 20...55,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} drove a company pickup through a safety checkpoint at 6:50 a.m. on {DATE}. The license check showed a revocation. {DL} says the boss told {D.him} to drive because no one else was on the crew that morning.",
        state: [E(.video, 3, "Checkpoint Camera", "{D}'s pickup stops at 6:50 a.m. and the officer asks for a license."),
                E(.document, 3, "DMV Record", "The license has been revoked for four months."),
                E(.document, 2, "Company Log", "{DL} is assigned to the pickup for the day.")],
        defense: [E(.statement, 1, "Boss's Order", "{DL} says the foreman told {D.him} to drive.")],
        role: "Highway patrol trooper",
        exam: [.direct("What is your position?", "\"I'm a highway patrol trooper, and I was working a safety checkpoint at dawn.\""), .direct("What happened?", "\"A company pickup came through at ten to seven, and I asked the driver for a license.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} had no license on {D.him} and gave a name and a birth date.\""), .direct("What did the check show?", "\"That {DL}'s license was revoked, and {D.he} wasn't allowed to drive.\""), .direct("What does the checkpoint camera show?", "\"{DL}'s pickup stopping, and me asking for a license, and {DL} shaking {D.his} head.\""), .direct("What did {DL} say about driving?", "\"{D.He} said the boss told {D.him} to drive because no one else was available.\""), .cross("The pickup was a company truck?", "\"Yes, it was a company truck, with the company's name on the door.\""), .cross("{DL} was polite?", "\"Yes, {D.he} was polite, and respectful, and answered every question.\""), .cross("{DL} didn't flee?", "\"No, {D.he} didn't try to flee, and {D.he} stopped the truck at the checkpoint.\""), .cross("The foreman wasn't at the checkpoint?", "\"No, the foreman wasn't at the checkpoint, but {D.he} told me about {D.him}.\""), .cross("{DL} told you the boss's name?", "\"Yes, {D.he} gave me the boss's name, and I wrote it in the report.\"")],
