                E(.statement, 2, "Crew Foreman", "A foreman says the car passed within six feet of a worker.")],
        defense: [E(.statement, 1, "Hidden Sign", "{DL} says a truck blocked the sign.")],
        role: "Highway patrol trooper",
        exam: [.direct("What is your assignment?", "\"I'm a highway patrol trooper, and I run radar on the interstate, including through marked work zones.\""), .direct("What did you see that afternoon?", "\"A car coming through a work zone at high speed, with crews working on the shoulder only feet from the lane.\""), .direct("What did your radar show?", "\"Seventy-eight miles an hour, at about two-fifteen in the afternoon, in a zone posted for forty-five.\""), .direct("What does your dash camera show?", "\"The radar reading, the cones lining the shoulder, and several workers in orange vests close to the passing car.\""), .direct("How are the signs posted?", "\"Every quarter mile, with reduced-speed signs, flashing lights, and a message board at the entrance to the zone.\""), .direct("What did {DL} say?", "\"{D.He} said a truck blocked the sign and that the lane looked clear.\""), .cross("A truck was parked near a sign?", "\"One work truck partly blocked one sign, but there were several others before it.\""), .cross("The lane ahead was clear?", "\"The travel lane was open, but the workers were right beside it on the shoulder.\""), .cross("{DL} slowed when you turned on your lights?", "\"Yes, {D.he} pulled over promptly and stayed polite throughout the stop.\""), .cross("No one was struck?", "\"No one was struck, though a worker told me the car passed within a few feet.\""), .cross("Seventy-eight is above the usual limit too?", "\"It's above the posted limit by thirty-three miles an hour, which is very serious in a work zone.\"")],
        theory: ("{D} sped through a work zone past a crew.", "{D} never saw the signs."),
        allocution: "\"I was running late, and I went through that work zone at seventy-eight miles an hour. The signs were hidden behind a truck, but that's no excuse, since crews were working right there on the shoulder. I'm sorry to the workers and to the trooper. I'll leave early and slow down.\"",
        truths: ("{DL} had been told to slow down by a flagger a mile earlier.", "A truck did block the first sign for several seconds."),
        defendant: [.direct("Were you going seventy-eight through the work zone?", "\"I was going too fast, but I didn't see the reduced-speed sign because a truck was blocking it.\""), .direct("Did you see the workers?", "\"Not until I was almost on them. The lane looked clear, and I thought the crews were farther off.\""), .direct("Did you see the other signs?", "\"I saw one earlier, but I thought the zone had ended. I wasn't paying close enough attention.\""), .direct("Why were you driving so fast?", "\"I was running late for work, and I let the clear road tempt me to speed up.\""), .direct("What did you do when the trooper stopped you?", "\"I pulled over right away, apologized, and told {TROOPER.him} I hadn't seen the sign.\""), .direct("What would you tell the road crew?", "\"I'm sorry for scaring you. I could have hurt one of you, and I'll slow down in every work zone.\""), .cross("You have been cited for speeding in a work zone before, haven't you?", "\"Yes, and I told the court I'd always slow down in work zones. I failed to do that.\""), .cross("Seventy-eight in a forty-five is nearly double the limit?", "\"It is, and I know that's reckless, whatever the signs looked like.\""), .cross("Several signs were posted before the one that was blocked?", "\"There were, and I should have noticed them and slowed down sooner.\""), .cross("You'll take a defensive driving class?", "\"Yes, I'll sign up for a class this month and finish every session.\""), .cross("You'll slow down in every work zone from now on?", "\"Yes, from now on I'll slow down at the first sign and stay slow until the zone ends.\"")],
        openings: ("A trooper clocked {D} at 78 miles per hour through a highway work zone, where crews were working on the shoulder with signs posted every quarter mile, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the signs were hidden behind a truck and the lane looked clear, and {D} did not see the reduced limit. {D} meant no danger to any worker."),
        closings: ("The trooper's radar shows 78 through a work zone with crews on the shoulder, signs every quarter mile, and having faced {PRIOR} before, {DL} understood exactly what the signs mean.", "Signs hidden behind a truck cannot warn a driver. The State must prove {D} saw the limit and sped past the crew."),
        timeline: [(0, "2:15 p.m.: the radar reading."), (0, "2:20 p.m.: the stop."), (3, "The foreman's statement is taken.")],
        identified: "Stopped at the scene.",
        notDone: ["The flagger's statement was never taken."],
        mood: .wantsConviction)

    static let consoleBaggie = SmallCases.make(
